"""The transcript switch's vocabulary as a STDLIB-ONLY Python copy for the CLI (no pydantic)."""

from __future__ import annotations

from ..probe_contracts import Contracts
from .client_messages import _python_enum

SOURCE = "contracts/probe_contracts/transcript_switch"

_PY_HEADER = (
    f"# GENERATED by `python -m probe_contracts.codegen` from {SOURCE}.\n"
    "# Do not edit: change the vocabulary there and rerun.\n"
)

_PY_PRELUDE = '''"""Whether a coding agent's sessions upload as transcripts, and who turned them off
(probe-contracts' transcript_switch). STDLIB ONLY: read on `probe status`'s local path.
"""

from __future__ import annotations

from enum import Enum

__all__ = [
{names}]


class _StrEnum(str, Enum):
    """3.11's StrEnum on 3.10 too: `str(member)` is its value."""

    def __str__(self) -> str:
        return str(self.value)
'''


def render_transcript_switch_stdlib(contracts: Contracts) -> str:
    names = "".join(f'    "{c.__name__}",\n' for c in sorted(contracts.transcript_switch, key=lambda c: c.__name__))
    blocks = [_python_enum(e) for e in contracts.transcript_switch]
    return _PY_HEADER + _PY_PRELUDE.format(names=names) + "".join(f"\n\n{block}" for block in blocks)
